//! POC citizen registration, password login, and password regeneration.
//!
//! No external verification (that needs a government licence). A citizen's four
//! fields (PAN, Aadhaar, DOB, username) are fingerprinted into an `identity_root`
//! that anchors a rolling Citizen-UID seed chain. A 16-char reversible password
//! (see janmat_identity::token) carries userId + creation time + that
//! fingerprint, so it is bound to all four fields and expires 24h after
//! creation. Login is by password only; after expiry a new password is
//! regenerated by re-entering the four fields.

use std::sync::Arc;
use std::time::{SystemTime, UNIX_EPOCH};

use axum::{
    Json,
    extract::{Path, State},
    http::StatusCode,
};
use janmat_identity::token;
use serde::{Deserialize, Serialize};

use crate::db::Registry;

const DAY_SECS: i64 = 24 * 60 * 60;

fn token_key() -> Vec<u8> {
    std::env::var("JANMAT_TOKEN_KEY")
        .unwrap_or_else(|_| "janmat-dev-token-key-change-me".to_string())
        .into_bytes()
}
fn now_secs() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs() as i64
}
fn fp_from_root_hex(h: &str) -> Option<[u8; 6]> {
    if h.len() < 12 {
        return None;
    }
    let mut fp = [0u8; 6];
    for (i, slot) in fp.iter_mut().enumerate() {
        *slot = u8::from_str_radix(&h[i * 2..i * 2 + 2], 16).ok()?;
    }
    Some(fp)
}

// ── Request / Response ──────────────────────────────────────────────────────────

#[derive(Deserialize)]
pub struct RegisterRequest {
    pub username: String,
    pub pan: String,
    pub aadhaar: String,
    pub dob: String,
    pub phone: String,
}

#[derive(Serialize)]
pub struct RegisterResponse {
    pub success: bool,
    pub username: String,
    pub uid: String,
    pub nullifier_seed_commitment: String,
    /// 16-char login password (valid 24h). Save it.
    pub password: String,
    pub password_expires_at_ms: i64,
    pub login_count: i64,
    pub citizenship_country: String,
    pub masked_aadhaar: String,
    pub masked_pan: String,
    pub masked_phone: String,
    pub phone_verified: bool,
}

#[derive(Deserialize)]
pub struct LoginRequest {
    pub password: String,
}

#[derive(Serialize)]
pub struct LoginResponse {
    pub success: bool,
    pub username: String,
    /// New Citizen-UID after this login (seed rotates every login).
    pub uid: String,
    pub prev_uid: String,
    pub login_count: i64,
    pub expires_at_ms: i64,
    pub citizenship_country: String,
}

#[derive(Deserialize)]
pub struct RegenRequest {
    pub username: String,
    pub pan: String,
    pub aadhaar: String,
    pub dob: String,
}

#[derive(Serialize)]
pub struct RegenResponse {
    pub success: bool,
    pub password: String,
    pub password_expires_at_ms: i64,
}

#[derive(Serialize)]
pub struct UsernameAvailability {
    pub username: String,
    pub available: bool,
    pub reason: Option<String>,
}

#[derive(Serialize)]
pub struct ApiError {
    pub success: bool,
    pub error: String,
    pub field: String,
}

type Fail = (StatusCode, Json<ApiError>);
fn fail(status: StatusCode, field: &str, msg: &str) -> Fail {
    (
        status,
        Json(ApiError {
            success: false,
            error: msg.to_string(),
            field: field.to_string(),
        }),
    )
}

// ── Validation ──────────────────────────────────────────────────────────────────

fn digits_only(s: &str) -> String {
    s.chars().filter(|c| c.is_ascii_digit()).collect()
}
fn normalize_phone(s: &str) -> Option<String> {
    let mut d = digits_only(s);
    if d.len() == 12 && d.starts_with("91") {
        d = d[2..].to_string();
    } else if d.len() == 11 && d.starts_with('0') {
        d = d[1..].to_string();
    }
    (d.len() == 10 && matches!(d.as_bytes()[0], b'6'..=b'9')).then_some(d)
}
fn valid_username(s: &str) -> bool {
    let n = s.chars().count();
    (3..=20).contains(&n)
        && s.chars().next().is_some_and(|c| c.is_ascii_alphabetic())
        && s.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
}
fn valid_pan(s: &str) -> bool {
    let b = s.as_bytes();
    s.len() == 10
        && b[0..5].iter().all(u8::is_ascii_alphabetic)
        && b[5..9].iter().all(u8::is_ascii_digit)
        && b[9].is_ascii_alphabetic()
}
fn valid_dob(s: &str) -> bool {
    let b = s.as_bytes();
    s.len() == 10
        && b[4] == b'-'
        && b[7] == b'-'
        && b[0..4].iter().all(u8::is_ascii_digit)
        && b[5..7].iter().all(u8::is_ascii_digit)
        && b[8..10].iter().all(u8::is_ascii_digit)
}

// ── Handlers ──────────────────────────────────────────────────────────────────

/// GET /citizen/username/{name}
pub async fn username_available(
    State(reg): State<Arc<Registry>>,
    Path(name): Path<String>,
) -> Result<Json<UsernameAvailability>, Fail> {
    let name = name.trim().to_string();
    if !valid_username(&name) {
        return Ok(Json(UsernameAvailability {
            username: name,
            available: false,
            reason: Some("Invalid format".into()),
        }));
    }
    let taken = reg.is_taken(&name).await.map_err(|_| {
        fail(
            StatusCode::INTERNAL_SERVER_ERROR,
            "server",
            "registry error",
        )
    })?;
    Ok(Json(UsernameAvailability {
        available: !taken,
        reason: taken.then(|| "Already taken".into()),
        username: name,
    }))
}

/// POST /citizen/register
pub async fn register(
    State(reg): State<Arc<Registry>>,
    Json(req): Json<RegisterRequest>,
) -> Result<Json<RegisterResponse>, Fail> {
    let username = req.username.trim().to_string();
    if !valid_username(&username) {
        return Err(fail(
            StatusCode::BAD_REQUEST,
            "username",
            "Username must be 3–20 chars, start with a letter, letters/digits/_ only.",
        ));
    }
    let pan = req.pan.trim().to_uppercase();
    if !valid_pan(&pan) {
        return Err(fail(
            StatusCode::BAD_REQUEST,
            "pan",
            "PAN must look like ABCDE1234F.",
        ));
    }
    let aadhaar = digits_only(&req.aadhaar);
    if aadhaar.len() != 12 {
        return Err(fail(
            StatusCode::BAD_REQUEST,
            "aadhaar",
            "Aadhaar must be 12 digits.",
        ));
    }
    if !valid_dob(&req.dob) {
        return Err(fail(
            StatusCode::BAD_REQUEST,
            "dob",
            "Date of birth must be YYYY-MM-DD.",
        ));
    }
    let Some(phone) = normalize_phone(&req.phone) else {
        return Err(fail(
            StatusCode::BAD_REQUEST,
            "phone",
            "Enter a valid 10-digit Indian mobile number.",
        ));
    };

    let root = token::identity_root(&pan, &aadhaar, &req.dob, &username);
    let root_hex = token::root_hex(&root);
    let seed0 = token::seed_genesis(&root_hex);
    let now = now_secs();
    let masked_phone = format!("XXXXXX{}", &phone[6..]);

    match reg
        .register(&username, &root_hex, &masked_phone, now, &seed0)
        .await
    {
        Ok(Some(id)) => {
            let fp = token::fingerprint6(&root);
            let password = token::encode_password(id, now as u32, &fp, &token_key());
            Ok(Json(RegisterResponse {
                success: true,
                username,
                uid: seed0.clone(),
                nullifier_seed_commitment: seed0,
                password,
                password_expires_at_ms: (now + DAY_SECS) * 1000,
                login_count: 0,
                citizenship_country: "India".into(),
                masked_aadhaar: format!("XXXX-XXXX-{}", &aadhaar[8..]),
                masked_pan: format!("XXXXXX{}", &pan[6..]),
                masked_phone,
                phone_verified: false,
            }))
        }
        Ok(None) => Err(fail(
            StatusCode::CONFLICT,
            "username",
            "That username is already taken. Please choose another.",
        )),
        Err(_) => Err(fail(
            StatusCode::INTERNAL_SERVER_ERROR,
            "server",
            "Could not register — registry error.",
        )),
    }
}

/// POST /citizen/login — password only.
pub async fn login(
    State(reg): State<Arc<Registry>>,
    Json(req): Json<LoginRequest>,
) -> Result<Json<LoginResponse>, Fail> {
    let bad = || fail(StatusCode::UNAUTHORIZED, "password", "Invalid password.");
    let (id, secs, fp) =
        token::decode_password(req.password.trim(), &token_key()).ok_or_else(bad)?;

    let citizen = reg
        .by_id(id)
        .await
        .map_err(|_| {
            fail(
                StatusCode::INTERNAL_SERVER_ERROR,
                "server",
                "registry error",
            )
        })?
        .ok_or_else(bad)?;

    // The password must match the currently-active one (creation time) …
    if secs as i64 != citizen.pwd_created {
        return Err(fail(
            StatusCode::UNAUTHORIZED,
            "password",
            "This password is no longer valid.",
        ));
    }
    // … and its embedded fingerprint must match all four registered fields.
    if fp_from_root_hex(&citizen.root) != Some(fp) {
        return Err(bad());
    }
    // … and it must not have expired.
    let now = now_secs();
    if now >= citizen.pwd_created + DAY_SECS {
        return Err(fail(
            StatusCode::UNAUTHORIZED,
            "password",
            "Password expired — regenerate it with your details.",
        ));
    }

    // Rotate the Citizen-UID seed chain (seed changes every login).
    let n = citizen.login_count + 1;
    let new_seed = token::seed_next(&citizen.current_seed, n as u64);
    reg.rotate_seed(&citizen.username, n, &new_seed)
        .await
        .map_err(|_| {
            fail(
                StatusCode::INTERNAL_SERVER_ERROR,
                "server",
                "registry error",
            )
        })?;

    Ok(Json(LoginResponse {
        success: true,
        username: citizen.username,
        uid: new_seed,
        prev_uid: citizen.current_seed,
        login_count: n,
        expires_at_ms: (citizen.pwd_created + DAY_SECS) * 1000,
        citizenship_country: "India".into(),
    }))
}

/// POST /citizen/password — regenerate after expiry (needs all four fields).
pub async fn regenerate(
    State(reg): State<Arc<Registry>>,
    Json(req): Json<RegenRequest>,
) -> Result<Json<RegenResponse>, Fail> {
    let username = req.username.trim().to_string();
    let citizen = reg
        .by_username(&username)
        .await
        .map_err(|_| {
            fail(
                StatusCode::INTERNAL_SERVER_ERROR,
                "server",
                "registry error",
            )
        })?
        .ok_or_else(|| {
            fail(
                StatusCode::NOT_FOUND,
                "username",
                "No citizen registered with that username.",
            )
        })?;

    let pan = req.pan.trim().to_uppercase();
    let aadhaar = digits_only(&req.aadhaar);
    let root = token::root_hex(&token::identity_root(&pan, &aadhaar, &req.dob, &username));
    if root != citizen.root {
        return Err(fail(
            StatusCode::UNAUTHORIZED,
            "info",
            "Those details don't match our records.",
        ));
    }

    let now = now_secs();
    if now < citizen.pwd_created + DAY_SECS {
        return Err(fail(
            StatusCode::CONFLICT,
            "active",
            "Your current password is still valid. A new one can be generated only after it expires.",
        ));
    }

    reg.set_pwd_created(&username, now).await.map_err(|_| {
        fail(
            StatusCode::INTERNAL_SERVER_ERROR,
            "server",
            "registry error",
        )
    })?;
    let fp = token::fingerprint6(&token::identity_root(&pan, &aadhaar, &req.dob, &username));
    let password = token::encode_password(citizen.id, now as u32, &fp, &token_key());

    Ok(Json(RegenResponse {
        success: true,
        password,
        password_expires_at_ms: (now + DAY_SECS) * 1000,
    }))
}
